fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length, we can iterate them in parallel.
    // For each index, compare a[i] < b[i] and collect the boolean results.
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x < y)
        .collect()
}